--- a/src/items.js
+++ b/src/items.js
@@ -6,10 +6,17 @@ export async function findByTag(tag) {
   return items.filter((item) => item.tags.includes(tag));
 }

+// Tail of the add queue: id assignment and save must not interleave.
+let addQueue = Promise.resolve();
+
 /** Adds an item with the next free id. */
 export async function addItem(item) {
   if (!item.name) throw new Error("Item needs a name.");
-  const items = await fetchItems();
-  const id = Math.max(0, ...items.map((i) => i.id)) + 1;
-  return saveItem({ tags: [], unit: "", ...item, id });
+  const run = addQueue.then(async () => {
+    const items = await fetchItems();
+    const id = Math.max(0, ...items.map((i) => i.id)) + 1;
+    return saveItem({ tags: [], unit: "", ...item, id });
+  });
+  addQueue = run.catch(() => {});
+  return run;
 }
