 });
+
+test("addItem gives concurrent adds distinct ids", async () => {
+  const added = await Promise.all([
+    addItem({ name: "salt", qty: 1 }),
+    addItem({ name: "pepper", qty: 1 }),
+    addItem({ name: "sugar", qty: 1 }),
+  ]);
+  const ids = added.map((i) => i.id);
+  assert.equal(new Set(ids).size, 3);
+});
